const char *NxtCustom_iconName(int i){return icons[i>=0&&i<300?i:0];}
const char *NxtCustom_iconLabel(int i){return nxt.language==1&&i>=0&&i<64?labels[i]:NxtCustom_iconName(i);}
const char *NxtCustom_emoji(int i){return emoji[i>=0&&i<64?i:0];}
const char *NxtCustom_menuIcon(int i){static const char *original[]={"library","list-music","heart","radio","headphones","settings-2","info"};if(i<0||i>=7)return "music-2";int v=nxt.menu_icons[i];if(v<=0)return original[i];if(v<=300)return icons[v-1];snprintf(menu_names[i],sizeof(menu_names[i]),"emoji-%d",v-301);return menu_names[i];}
static void glyph(SDL_Surface *s,const char *t,int x,int y,int size,SDL_Color c){if(size<1||!s->w)return;NxtSkin_fitText(s,size*1024/s->w,t,x,y,size,size,c,true);}
