int NxtCustom_gallery(DisplayContext *d,bool emojis,int initial){int count=emojis?180:300;int selected=initial>=0&&initial<count?initial:0,show=0;uint32_t drawn=0;for(;;){int old=selected;ModuleCommon_frameBegin();SDL_Surface *s=DisplayHelper_getSurface(d);GlobalInputResult g=ModuleCommon_handleGlobalInput(s,&show,HELP_NONE);if(g.should_quit)return -2;if(!g.input_consumed&&!Nxt_lockInput()){if(NxtPad_justPressed(BTN_B))return -1;if(NxtPad_justPressed(BTN_A))return selected;if(!!NxtPad_justRepeated(BTN_LEFT))selected=(selected+count-1)%count;if(!!NxtPad_justRepeated(BTN_RIGHT))selected=(selected+1)%count;if(!!NxtPad_justRepeated(BTN_UP))selected=(selected+count-6)%count;if(!!NxtPad_justRepeated(BTN_DOWN))selected=(selected+6)%count;if(NxtPad_justPressed(BTN_L1))selected=(selected+count-24)%count;if(NxtPad_justPressed(BTN_R1))selected=(selected+24)%count;}if(NxtSkin_shouldDraw(drawn,g.dirty||old!=selected)){char page[64];snprintf(page,sizeof(page),"%d / %d",selected+1,count);NxtSkin_begin(s,emojis?Nxt_text("Emoji","Emoji"):Nxt_text("Symbols","Biểu tượng"),page,false);int u=s->w,first=selected/24*24;for(int i=first;i<first+24&&i<count;i++){int k=i-first;SDL_Rect r={(32+k%6*162)*u/1024,(153+k/6*121)*u/1024,150*u/1024,109*u/1024};SDL_Color c=NxtSkin_color(i==selected?NXT_ACCENT_INK:NXT_INK);NxtSkin_rect(s,r,NxtSkin_color(i==selected?NXT_ACCENT:NXT_PANEL),9*u/1024);char name[32];snprintf(name,sizeof(name),"emoji-%d",i);NxtSkin_icon(s,emojis?name:icons[i],r.x+49*u/1024,r.y+9*u/1024,52*u/1024,c);char num[32];snprintf(num,sizeof(num),"%s",emojis?emoji_names[i]:"");NxtSkin_text(s,16,emojis?num:NxtCustom_iconLabel(i),r.x+8*u/1024,r.y+70*u/1024,r.w-16*u/1024,c);}NxtSkin_footer(s,Nxt_text("D-pad Select · L1/R1 Pages · A Apply · B Back","D-pad Chọn · L1/R1 Trang · A Áp dụng · B Về"),false);ModuleCommon_markSurfaceDrawn();drawn=SDL_GetTicks();}ModuleCommon_frameEnd(s);}}
ModuleExitReason NxtCustom_rgb(DisplayContext *d,const char *title,int *value){int old=*value,component=0,show=0;unsigned rgb=(unsigned)*value&0xffffff;uint32_t drawn=0;for(;;){ModuleCommon_frameBegin();SDL_Surface *s=DisplayHelper_getSurface(d);GlobalInputResult g=ModuleCommon_handleGlobalInput(s,&show,HELP_NONE);bool dirty=g.dirty;if(g.should_quit){*value=old;return MODULE_EXIT_QUIT;}if(!g.input_consumed&&!Nxt_lockInput()){if(NxtPad_justPressed(BTN_B)){*value=old;return MODULE_EXIT_TO_MENU;}if(NxtPad_justPressed(BTN_A)){*value=rgb;Nxt_save();return MODULE_EXIT_TO_MENU;}if(!!NxtPad_justRepeated(BTN_UP)){component=(component+2)%3;dirty=true;}if(!!NxtPad_justRepeated(BTN_DOWN)){component=(component+1)%3;dirty=true;}int delta=!!NxtPad_justRepeated(BTN_RIGHT)-!!NxtPad_justRepeated(BTN_LEFT)+16*(!!NxtPad_justRepeated(BTN_R1)-!!NxtPad_justRepeated(BTN_L1));if(delta){int shift=(2-component)*8,v=((rgb>>shift)&255)+delta;if(v<0)v=0;if(v>255)v=255;rgb=(rgb&~(255u<<shift))|((unsigned)v<<shift);dirty=true;}if(NxtPad_justPressed(BTN_X)){char *t=Keyboard_openLatin("HEX RRGGBB",7);if(t){char *p=t;if(*p=='#')p++;bool valid=strlen(p)==6;for(int k=0;valid&&k<6;k++)valid=isxdigit((unsigned char)p[k]);if(valid)rgb=strtoul(p,NULL,16);else Toast_show(Nxt_text("Enter 6 HEX digits","Nhập 6 ký tự HEX"),2000);free(t);dirty=true;}}}if(NxtSkin_shouldDraw(drawn,dirty)){NxtSkin_begin(s,title,NULL,false);int u=s->w;SDL_Color c={rgb>>16,(rgb>>8)&255,rgb&255,255};NxtSkin_rect(s,(SDL_Rect){40*u/1024,154*u/1024,250*u/1024,141*u/1024},c,16*u/1024);char t[64];snprintf(t,sizeof(t),"#%06X",rgb);NxtSkin_text(s,40,t,338*u/1024,180*u/1024,616*u/1024,NxtSkin_color(NXT_INK));for(int i=0;i<3;i++){int y=(337+i*77)*u/1024,v=(rgb>>((2-i)*8))&255;snprintf(t,sizeof(t),"%c  %3d","RGB"[i],v);NxtSkin_text(s,27,t,43*u/1024,y,160*u/1024,NxtSkin_color(i==component?NXT_ACCENT:NXT_INK));NxtSkin_rect(s,(SDL_Rect){230*u/1024,y+10*u/1024,722*u/1024,24*u/1024},NxtSkin_color(NXT_PANEL),8*u/1024);NxtSkin_rect(s,(SDL_Rect){230*u/1024,y+10*u/1024,722*u/1024*v/255,24*u/1024},(SDL_Color){i==0?255:40,i==1?255:40,i==2?255:40,255},8*u/1024);}NxtSkin_footer(s,Nxt_text("↑↓ RGB · ←→ ±1 · L1/R1 ±16 · X HEX · A Save · B Cancel","↑↓ RGB · ←→ ±1 · L1/R1 ±16 · X HEX · A Lưu · B Hủy"),false);ModuleCommon_markSurfaceDrawn();drawn=SDL_GetTicks();}ModuleCommon_frameEnd(s);}}
ModuleExitReason NxtCustom_avatarEdit(DisplayContext *d){int selected=0;for(;;){const char *rows[]={Nxt_text("Symbols","Biểu tượng"),Nxt_text("Emoji","Emoji"),Nxt_text("Letters","Chữ"),Nxt_text("Photo","Ảnh")};NxtPick p=Nxt_pick(d,Nxt_text("Your avatar","Avatar của bạn"),rows,4,&selected,Nxt_text("A Choose · B Back","A Chọn · B Về"));if(p.action==2||p.action==9)return p.action==9?MODULE_EXIT_QUIT:MODULE_EXIT_TO_MENU;if(p.action!=1)continue;
 if(selected<2){int i=NxtCustom_gallery(d,selected==1,selected==1?nxt.avatar_emoji:nxt.avatar_icon);if(i==-2)return MODULE_EXIT_QUIT;if(i<0)continue;if(selected==0)nxt.avatar_icon=i;else nxt.avatar_emoji=i;nxt.avatar_mode=selected;}
 else if(selected==2){char *t=Keyboard_open(Nxt_text("Avatar letters / emoji","Chữ / emoji avatar"),16);if(t){snprintf(nxt.avatar_text,sizeof(nxt.avatar_text),"%s",t);free(t);nxt.avatar_mode=2;}}
 else if(selected==3){char input[512];if(!Nxt_chooseFile(d,".jpg",".png",input))continue;uint32_t w,h;SDL_Surface *raw=NULL,*small=NULL;if(NxtWallpaper_imageSize(input,&w,&h)&&w<=8192&&h<=8192&&(uint64_t)w*h<=16000000)raw=IMG_Load(input);if(raw){small=fit_photo(raw);SDL_FreeSurface(raw);}char rel[160],path[1200],tmp[1220];snprintf(rel,sizeof(rel),"listeners/%d",NxtPersonal_id());userdata_mkdir(rel);snprintf(rel,sizeof(rel),"listeners/%d/avatar.png",NxtPersonal_id());userdata_snpath(rel,path,sizeof(path));snprintf(tmp,sizeof(tmp),"%s.tmp",path);if(small&&strlen(path)<sizeof(nxt.avatar_path)&&IMG_SavePNG(small,tmp)==0&&rename(tmp,path)==0){memcpy(nxt.avatar_path,path,strlen(path)+1);nxt.avatar_mode=3;NxtCustom_release();}else {unlink(tmp);Toast_show(Nxt_text("Cannot import this image","Chưa nhập được ảnh này"),2500);}if(small)SDL_FreeSurface(small);}

 Nxt_save();}
}
ModuleExitReason NxtCustom_menu(DisplayContext *d){int selected=0;for(;;){const char *names[]={Nxt_text("Library","Thư viện"),"Playlist",Nxt_text("Favorites","Yêu thích"),Nxt_text("Online music","Nhạc online"),Nxt_text("Personal","Cá nhân"),Nxt_text("Settings","Cài đặt"),Nxt_text("About & updates","Thông tin & cập nhật"),Nxt_text("Restore original icons","Khôi phục icon gốc")};NxtPick p=Nxt_pick(d,Nxt_text("Change menu icons","Đổi biểu tượng menu"),names,8,&selected,Nxt_text("A Edit · X Original · B Back","A Sửa · X Mặc định · B Về"));if(p.action==2||p.action==9)return p.action==9?MODULE_EXIT_QUIT:MODULE_EXIT_TO_MENU;if(p.action==3&&selected<7){nxt.menu_icons[selected]=0;Nxt_save();}if(p.action!=1)continue;if(selected==7){memset(nxt.menu_icons,0,sizeof(nxt.menu_icons));Nxt_save();continue;}int type=0;const char *types[]={Nxt_text("Icon","Biểu tượng"),"Emoji",Nxt_text("Original","Mặc định")};NxtPick t=Nxt_pick(d,names[selected],types,3,&type,Nxt_text("A Choose · B Back","A Chọn · B Về"));if(t.action==9)return MODULE_EXIT_QUIT;if(t.action!=1)continue;if(type==2)nxt.menu_icons[selected]=0;else{int current=nxt.menu_icons[selected],i=NxtCustom_gallery(d,type==1,type==1?current-301:current-1);if(i==-2)return MODULE_EXIT_QUIT;if(i<0)continue;nxt.menu_icons[selected]=i+(type==1?301:1);}Nxt_save();}}
