const char *NxtCustom_genre(int i){static const char *vi[]={"Pop","Nhạc Việt","K-pop","J-pop","Nhạc Hoa","Nhạc Thái","Mộc","Jazz","Piano","Lo-fi","Rock","EDM","Cổ điển","Không gian","Soul","R&B","Hip-hop","Indie","Dân gian","Hoài cổ"};i=i>=0&&i<20?i:0;return Nxt_text(genres[i],vi[i]);}
const char *NxtCustom_mood(int i){static const char *vi[]={"Khám phá","Thư giãn","Tập trung","Vui vẻ","Buồn","Ngủ","Tập luyện","Du lịch","Lãng mạn","Năng lượng"};i=i>=0&&i<10?i:0;return Nxt_text(moods[i],vi[i]);}
void NxtCustom_query(char *out,size_t n,int kind){
 static const char *country[]={"","Vietnam","Korea","Japan","United States","United Kingdom","France","Thailand","Germany","China","Taiwan","Brazil","Italy","Indonesia","Russia","Spain"};
 snprintf(out,n,"%s %s %s%s",genres[nxt.genre],nxt.mood?moods[nxt.mood]:"",country[nxt.country>=0&&nxt.country<16?nxt.country:0],kind==3?" acoustic":kind==4?" live":"");
}
ModuleExitReason NxtCustom_spectrum(DisplayContext *d){int selected=0;for(;;){char palette[120],mode[120],c1[120],c2[120];static const char *modes[]={"Solid","Gradient","7-color Rainbow","VU","Multicolor Mix"};snprintf(palette,sizeof(palette),"%s\t%s",Nxt_text("Palette","Bảng màu"),Spectrum_paletteName(nxt.spectrum_palette));snprintf(mode,sizeof(mode),"%s\t%s",Nxt_text("Style","Kiểu"),modes[nxt.spectrum_mode]);snprintf(c1,sizeof(c1),"RGB 1\t#%06X",nxt.spectrum_rgb);snprintf(c2,sizeof(c2),"RGB 2\t#%06X",nxt.spectrum_rgb2);const char *rows[]={palette,mode,c1,c2,Nxt_text("Show / hide spectrum","Bật / tắt phổ nhạc")};NxtPick p=Nxt_pick(d,Nxt_text("Spectrum colors","Màu phổ nhạc"),rows,4,&selected,Nxt_text("←/→ Change · A Edit · B Back","←/→ Đổi · A Sửa · B Về"));if(p.action==2||p.action==9)return p.action==9?MODULE_EXIT_QUIT:MODULE_EXIT_TO_MENU;if(p.action!=1&&p.action!=5&&p.action!=6)continue;int delta=p.action==5?-1:1;if(selected==0)nxt.spectrum_palette=(nxt.spectrum_palette+21+delta)%21;else if(selected==1)nxt.spectrum_mode=(nxt.spectrum_mode+5+delta)%5;else if(selected==2||selected==3){nxt.spectrum_palette=20;if(NxtCustom_rgb(d,selected==2?"Spectrum RGB 1":"Spectrum RGB 2",selected==2?&nxt.spectrum_rgb:&nxt.spectrum_rgb2)==MODULE_EXIT_QUIT)return MODULE_EXIT_QUIT;}else Spectrum_toggleVisible();Nxt_save();}}
